package com.moviebooking.notification.entity;
import com.moviebooking.notification.enums.*; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications", indexes={@Index(name="idx_notification_user",columnList="user_id"),@Index(name="idx_notification_booking",columnList="booking_id"),@Index(name="idx_notification_event",columnList="event_id"),@Index(name="idx_notification_created",columnList="created_at")}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="event_id",nullable=false,unique=true,length=100) private String eventId; @Column(name="user_id",nullable=false,length=100) private String userId; @Column(name="booking_id",length=100) private String bookingId; @Column(nullable=false,length=320) private String recipient; @Enumerated(EnumType.STRING) @Column(name="notification_type",nullable=false) private NotificationType notificationType; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationChannel channel; @Column(nullable=false,length=255) private String subject; @Lob @Column(nullable=false,columnDefinition="TEXT") private String message; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationStatus status; @Column(name="failure_reason",length=1000) private String failureReason; @Column(name="read_at") private LocalDateTime readAt; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="sent_at") private LocalDateTime sentAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void created(){LocalDateTime now=LocalDateTime.now();createdAt=now;updatedAt=now;} @PreUpdate void updated(){updatedAt=LocalDateTime.now();} }
